//! Generate verification keys for mainnet deployment using seed 42.
//!
//! This binary produces three VK JSON files (small, medium, large tiers)
//! that match the proving keys generated by the mobile apps' default
//! `generateTestingProvingKey(tier, seed=42)` call.
//!
//! Usage:
//!   cargo run --release --bin generate_mainnet_vks -- --out-dir /path/to/output

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

use ark_bls12_381::{Bls12_381, G1Affine, G2Affine};
use ark_groth16::VerifyingKey;
use ark_serialize::CanonicalSerialize;
use rand::SeedableRng;
use rand_chacha::ChaCha20Rng;

use sep_xxxx_circuits::prover;

/// The seed used by both iOS and Android apps for `generateTestingProvingKey`.
const APP_DEFAULT_SEED: u64 = 42;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out_dir = parse_out_dir(env::args().skip(1))?;
    fs::create_dir_all(&out_dir)?;

    eprintln!("Generating verification keys with seed {APP_DEFAULT_SEED} ...");

    eprintln!("  Small tier (depth 5, max 32 members)");
    let small = deterministic_setup(5)?;
    write_string(&out_dir.join("vk-small.json"), &verification_key_json(&small))?;

    eprintln!("  Medium tier (depth 8, max 256 members)");
    let medium = deterministic_setup(8)?;
    write_string(&out_dir.join("vk-medium.json"), &verification_key_json(&medium))?;

    eprintln!("  Large tier (depth 11, max 2048 members)");
    let large = deterministic_setup(11)?;
    write_string(&out_dir.join("vk-large.json"), &verification_key_json(&large))?;

    eprintln!("Done. VK files written to {}", out_dir.display());
    Ok(())
}

fn parse_out_dir(mut args: impl Iterator<Item = String>) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut out_dir: Option<PathBuf> = None;
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--out-dir" => {
                let value = args.next().ok_or("--out-dir requires a value")?;
                out_dir = Some(PathBuf::from(value));
            }
            _ => return Err(format!("unknown argument: {arg}").into()),
        }
    }
    out_dir.ok_or_else(|| "--out-dir is required".into())
}

fn deterministic_setup(depth: usize) -> Result<VerifyingKey<Bls12_381>, Box<dyn std::error::Error>> {
    let mut rng = ChaCha20Rng::seed_from_u64(APP_DEFAULT_SEED);
    let setup = prover::setup(depth, &mut rng)?;
    Ok(setup.verifying_key)
}

fn verification_key_json(vk: &VerifyingKey<Bls12_381>) -> String {
    let ic = vk
        .gamma_abc_g1
        .iter()
        .map(|point| format!("\"{}\"", hex_encode(&serialize_g1(point))))
        .collect::<Vec<_>>()
        .join(",");

    format!(
        concat!(
            "{{",
            "\"alpha_g1\":\"{}\",",
            "\"beta_g2\":\"{}\",",
            "\"gamma_g2\":\"{}\",",
            "\"delta_g2\":\"{}\",",
            "\"ic\":[{}]",
            "}}\n"
        ),
        hex_encode(&serialize_g1(&vk.alpha_g1)),
        hex_encode(&serialize_g2(&vk.beta_g2)),
        hex_encode(&serialize_g2(&vk.gamma_g2)),
        hex_encode(&serialize_g2(&vk.delta_g2)),
        ic,
    )
}

fn serialize_g1(point: &G1Affine) -> Vec<u8> {
    let mut bytes = Vec::new();
    point.serialize_uncompressed(&mut bytes).expect("G1 serialization");
    bytes
}

fn serialize_g2(point: &G2Affine) -> Vec<u8> {
    let mut bytes = Vec::new();
    point.serialize_uncompressed(&mut bytes).expect("G2 serialization");
    bytes
}

fn hex_encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(nibble_to_hex(byte >> 4));
        out.push(nibble_to_hex(byte & 0x0f));
    }
    out
}

fn nibble_to_hex(nibble: u8) -> char {
    match nibble {
        0..=9 => (b'0' + nibble) as char,
        10..=15 => (b'a' + (nibble - 10)) as char,
        _ => unreachable!(),
    }
}

fn write_string(path: &Path, contents: &str) -> Result<(), Box<dyn std::error::Error>> {
    fs::write(path, contents)?;
    Ok(())
}
